<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\Accessor\UserRoleAssignamentRolesRoleAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserRoleAssignamentRolesRoleAccessor trait.
 *
 * Covers null default, string/VO assignment via withRole,
 * getRole/role accessors, and isRoleChanged with/without original.
 */
class UserRoleAssignamentRolesRoleAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRole creates a new instance with the Role set
     * from a string value, and getRole returns the primitive string.
     */
    public function testWithRoleFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignamentRolesRoleAccessorUnitTest();

        // Act
        $result = $holder->withRole(new RoleRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new RoleRef('one'), $result->getRole());
    }
    /**
     * Asserts that withrole has access to the value object
     * from a string value, and getRole returns the primitive string.
     */
    public function testWithRoleFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignamentRolesRoleAccessorUnitTest();

        // Act
        $result = $holder->withRole(new RoleRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new RoleRef('one'), $result->role()->value());
    }
    public function testChangedRole(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignamentRolesRoleAccessorUnitTest()->withRole(new RoleRef('one'));
        $original = $holder->withRole(new RoleRef('one'));
        $same = $holder->withRole(new RoleRef('one'));
        $modified = $holder->withRole(new RoleRef('other'));

        // Act
        $withSame = $original->isRoleChanged($same);
        $withDiferent = $original->isRoleChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserRoleAssignamentRolesRoleAccessorUnitTest
{
    use UserRoleAssignamentRolesRoleAccessor;
}
